; vdp.asm -- chapter 3: the VDP's two ports: data, and control and status
; generated by gen03.py
        INCLUDE "msx.inc"
        OUTPUT "vdp.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
got     EQU VARS + 16           ; 4 bytes read back through port $98
st1     EQU VARS + 20           ; the status, read twice
st2     EQU VARS + 21
st3     EQU VARS + 22           ; port $99 read just after a register write
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        VRAM_WRITE $3FFE        ; four bytes from two before the end
        ld a, $11
        out (VDP_DATA), a
        ld a, $22
        out (VDP_DATA), a
        ld a, $33
        out (VDP_DATA), a
        ld a, $44
        out (VDP_DATA), a
        ld a, low $3FFE        ; the same address, to read: bit 6 left 0
        out (VDP_CTRL), a
        ld a, high $3FFE
        out (VDP_CTRL), a
        ld hl, got
        ld b, 4
.rd:    in a, (VDP_DATA)        ; each IN moves the address on, like each OUT
        ld (hl), a
        inc hl
        djnz .rd
        VDP_REG 1, $C0          ; display on, no interrupts
.wait:  in a, (VDP_CTRL)        ; the status, until the frame flag comes up
        rlca
        jr nc, .wait
        rrca
        ld (st1), a             ; the read that saw the flag
        in a, (VDP_CTRL)
        ld (st2), a             ; and the next one
        VDP_REG 7, $F4          ; a register write ...
        in a, (VDP_CTRL)        ; ... and port $99 read straight after it
        ld (st3), a
        VDP_REG 7, $0F          ; the border white again
        VDP_REG 1, $80          ; display off: the page is drawn
        ld b, 2
        ld c, 0
        ld hl, t_wrote
        call puts
        ld a, $11
        call puthex
        inc c
        ld a, $22
        call puthex
        inc c
        ld a, $33
        call puthex
        inc c
        ld a, $44
        call puthex
        inc c
        ld b, 4
        ld c, 0
        ld hl, t_read
        call puts
        ld hl, got
        ld e, 4
.show:  ld a, (hl)
        call puthex
        inc c
        inc hl
        dec e
        jr nz, .show
        ld b, 6
        ld c, 0
        ld hl, t_st
        call puts
        ld a, (st1)
        call puthex
        inc c
        ld a, (st2)
        call puthex
        ld b, 8
        ld c, 0
        ld hl, t_reg
        call puts
        ld a, (st3)
        call puthex
        VDP_REG 1, $C0          ; display on: the page is finished
done:   jr done

t_wrote: db "wrote at $3FFE: ", 0
t_read: db "read from $3FFE: ", 0
t_st:   db "status, twice:   ", 0
t_reg:  db "R#7 <- F4, then $99: ", 0

; at: B = row (0-23), C = column (0-31) -> the VDP's write address is that
;     cell of the name table. Keeps BC, DE. Uses A, HL.
at:     push de
        ld l, b
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; row x 32
        ld e, c
        ld d, $18
        add hl, de              ; + $1800 + column
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        pop de
        ret

; putc: A = character, B = row, C = column. Keeps BC, DE, HL.
putc:   push hl
        push af
        call at
        pop af
        out (VDP_DATA), a
        pop hl
        ret

; puts: HL = text ending in 0, B = row, C = column; C moves on.
puts:   ld a, (hl)
        or a
        ret z
        call putc
        inc hl
        inc c
        jr puts

; puthex: A = a byte, as two hexadecimal digits; C moves on by 2.
puthex: push af
        rrca
        rrca
        rrca
        rrca                    ; the high four bits first
        call hexdig
        pop af
hexdig: and %00001111
        add a, '0'
        cp '9' + 1
        jr c, .digit
        add a, 'A' - '9' - 1    ; 10-15 become A-F
.digit: call putc
        inc c
        ret
boxes:                          ; characters 1 (empty box) and 2 (filled)
        db %11111110, %10000010, %10000010, %10000010, %10000010, %10000010, %11111110, %00000000
        db %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %00000000
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
